/**
 * Cross-realm serialization for the offline shipping queues (story 264).
 *
 * Both queues are drained from TWO realms: the page (startup, the `online`
 * handler, and the estimate-review screen's 2.5 s poll) and the service worker's
 * Background Sync handler. Each realm loads its own module instance, so the
 * in-realm single-flight guard in `estimate-submit-shipping.ts` cannot see the
 * other one — and `requestEstimateSubmitSync()` is called immediately after the
 * page's own drain kick, so Chrome fires `sync` while the page drain is still
 * mid-upload.
 *
 * Measured in the lifecycle e2e (`health-ai-estimate-slow-upload.spec.ts`): the
 * two realms issued the SAME `POST /api/files/images` 4 ms apart, both having
 * read the entry while `image_path` was still empty. The server stored the photo
 * twice and one row was orphaned on arrival — the exact outcome story 264 exists
 * to stop. Removing the service worker's 15 s cap widened that window from
 * milliseconds to the whole upload, so the lock ships with it.
 *
 * Web Locks is the same mechanism story 214 uses for the OPFS file
 * (`db/db-coordination.ts`), works in windows and service workers alike, and
 * needs no dependency. We **wait** rather than skip: a skipping second drain
 * would resolve the SW's `sync` event without shipping anything, consuming the
 * Background Sync registration while the page drain might still fail. Waiting
 * means the second drain runs after the first and finds the entry already
 * submitted (or its `image_path` already persisted), so it re-uploads nothing and
 * `event.waitUntil` still reports the truth.
 */

/** One lock per queue: shipping photos must not block shipping estimate submits. */
export const ESTIMATE_SUBMIT_DRAIN_LOCK = 'motivation-estimate-submit-drain';
export const IMAGE_UPLOAD_DRAIN_LOCK = 'motivation-image-upload-drain';

/** Subset of LockManager the helper needs; undefined when Web Locks is absent. */
export type LocksApi = Pick<LockManager, 'request'> | undefined;

/**
 * The ambient Web Locks API, or undefined where there is none (jsdom under
 * vitest). Read defensively so the same accessor works in a window and in a
 * service worker — mirrors `db.worker.ts`'s `getLocks()`.
 */
export function getQueueLocks(): LocksApi {
    if (typeof navigator === 'undefined') return undefined;
    return (navigator as { locks?: LockManager }).locks;
}

/**
 * Run `drain` while holding the named queue's exclusive lock.
 *
 * The wait is bounded well above the 180 s upload budget
 * (`files.service.ts` → `IMAGE_UPLOAD_BUDGET_MS`): a longer wait means a realm is
 * genuinely stuck mid-drain, which fails loudly rather than hanging forever —
 * same rule as `withExclusiveDbLock`. Without a locks API the drain runs
 * directly, which is the pre-story-264 behaviour.
 */
export async function withQueueDrainLock<T>(
    locks: LocksApi,
    name: string,
    drain: () => Promise<T>,
    { timeoutMs = 200_000 }: { timeoutMs?: number } = {},
): Promise<T> {
    if (!locks) {
        return drain();
    }
    try {
        return await locks.request(
            name,
            { mode: 'exclusive', signal: AbortSignal.timeout(timeoutMs) },
            drain,
        ) as T;
    } catch (err) {
        if (err instanceof DOMException && (err.name === 'AbortError' || err.name === 'TimeoutError')) {
            throw new Error(
                `Timed out after ${timeoutMs}ms waiting for the "${name}" queue drain lock — `
                + 'another realm (window or service worker) may be stuck mid-drain.',
            );
        }
        throw err;
    }
}
